<script setup lang="ts">
import type {Product,CartLine} from '@ellas/shared';
useSeo('Hacer un pedido','Busca prendas, elige colores y reparte tallas y cantidades para vestir a todo tu equipo en un solo pedido.');
const route=useRoute();const selection=useSelection();const active=ref('');const opened=ref<Product[]>([]);const review=ref(false);const error=ref('');const notice=ref('');const pending=reactive<Record<string,boolean>>({});const candidate=ref<Product|null>(null);const configs=ref<Record<string,{clearAdded:()=>void}>>({});const checking=ref(false);
const savedRefs=computed(()=>Object.entries(selection.drafts).filter(([,draft])=>Object.values(draft.quantities).some(v=>Number(v)>0)).map(([reference])=>reference));
async function resume(reference:string){try{choose(await $fetch<Product>(`/api/catalog/products/${reference}`));}catch{error.value='No se ha encontrado esa prenda.';}}
function switchTo(product:Product){if(!opened.value.some(p=>p.reference===product.reference))opened.value.push(product);active.value=product.reference;candidate.value=null;review.value=false;notice.value='';}
function choose(product:Product){if(active.value!==product.reference && pending[active.value])candidate.value=product;else switchTo(product);}
function change(discard:boolean){if(!candidate.value)return;if(discard){delete selection.drafts[active.value];opened.value=opened.value.filter(p=>p.reference!==active.value);}switchTo(candidate.value);}
function add(lines:CartLine[],reference:string){if(selection.add(lines)){error.value='';configs.value[reference]?.clearAdded();notice.value=lines.reduce((n,l)=>n+l.quantity,0)+' prendas añadidas al pedido.';}else error.value=selection.validation;}
async function validate(){error.value='';if(!selection.lines.length)return;if(savedRefs.value.length){error.value='Tienes cantidades sin añadir en '+savedRefs.value.join(', ')+'. Añádelas o descártalas antes de continuar.';return;}checking.value=true;try{if(selection.lines.some(l=>!Number.isInteger(l.quantity)||l.quantity<1||l.quantity>10000))throw new Error('Revisa las cantidades: usa enteros entre 1 y 10.000 por talla.');const refs=[...new Set(selection.lines.map(l=>l.reference))];const data=await $fetch<{products:Product[]}>('/api/catalog/resolve',{query:{refs:refs.join(',')}});for(const line of selection.lines){const product=data.products.find(p=>p.reference===line.reference);if(!product?.source.reviewed||!product.colors.some(c=>c.code===line.color&&c.sizes.includes(line.size)))throw new Error(`Revisa ${line.reference}, ${line.color}, ${line.size}: esa combinación ha cambiado. Las demás prendas se conservan.`);}review.value=true;window.scrollTo({top:0,behavior:'smooth'});}catch(e){error.value=e instanceof Error?e.message:errorMessage(e);}finally{checking.value=false;}}
onMounted(async()=>{if(typeof route.query.ref==='string'&&/^[A-Z0-9]{2,50}$/i.test(route.query.ref)){try{choose(await $fetch<Product>(`/api/catalog/products/${route.query.ref}`));}catch{error.value='No se ha encontrado esa prenda. Puedes buscar otra.';}}});
watch(()=>route.query.ref,async ref=>{if(typeof ref==='string'&&/^[A-Z0-9]{2,50}$/i.test(ref)){try{choose(await $fetch<Product>(`/api/catalog/products/${ref}`));}catch{error.value='No se ha encontrado esa prenda.';}}});
</script>
<template><div class="order-page"><div class="container"><div class="breadcrumb"><NuxtLink to="/">Inicio</NuxtLink><span>/</span><span>Hacer un pedido</span></div><header class="order-page-heading"><span class="eyebrow">MUCHAS TALLAS. UN SOLO PEDIDO.</span><h1>Viste a tu equipo.<br/><span class="serif-word">En un solo pedido.</span></h1><p>Encuentra la prenda. Elige color. Reparte las tallas. Así de fácil.</p></header><nav class="order-progress" aria-label="Pasos del pedido"><button :class="{active:!review}" @click="review=false"><b>01</b> Añadir prendas</button><span/><button :class="{active:review}" :disabled="!selection.lines.length" @click="validate"><b>02</b> Revisar y enviar</button></nav><p v-if="selection.restoreWarning" class="alert" role="status">{{selection.restoreWarning}}</p><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-show="!review" class="order-workspace"><section class="order-work-area"><ProductSearch @select="choose"/><p class="order-search-tip">Por nombre, referencia o tejido. <NuxtLink to="/comparar">¿Dudas entre varias? Compáralas.</NuxtLink></p><div v-if="candidate" class="alert pending-choice" role="alert"><div><b>Tienes cantidades sin añadir.</b><p>¿Cómo quieres pasar a {{candidate.name}}?</p><button class="button dark" @click="change(false)">Conservar borrador y cambiar</button><button class="text-link" @click="change(true)">Descartar cantidades y cambiar</button><button class="text-link" @click="candidate=null">Seguir aquí</button></div></div><ClientOnly><div v-if="savedRefs.length" class="saved-configs"><span class="fine-print">Continúa un borrador de prenda guardado</span><button v-for="reference in savedRefs" :key="reference" @click="resume(reference)">{{reference}} <AppIcon name="ArrowRight" :size="12"/></button></div><VariantConfigurator v-for="product in opened" v-show="active===product.reference" :key="product.reference" :ref="el=>{if(el)configs[product.reference]=el as unknown as {clearAdded:()=>void}}" :product="product" @pending="pending[product.reference]=$event" @add="add($event,product.reference)"/><div v-if="!opened.length" class="order-start"><span class="order-start-icon"><AppIcon name="Shirt" :size="38"/></span><h2>Tu equipo empieza aquí.</h2><p>Escribe arriba qué buscas y te ayudamos a encontrarlo.</p><div><button v-for="ref in ['JT150','JTPOLO','JTSWKNG']" :key="ref" class="button outline" @click="async()=>choose(await $fetch<Product>(`/api/catalog/products/${ref}`))">{{ref}} <AppIcon name="Plus" :size="15"/></button></div></div><div v-if="opened.length>1" class="saved-configs"><span class="fine-print">Prendas que estás preparando</span><button v-for="p in opened" :key="p.reference" :aria-pressed="active===p.reference" @click="choose(p)">{{p.reference}}<small v-if="pending[p.reference]">Borrador</small></button></div></ClientOnly><p v-if="notice" class="alert success" role="status">{{notice}}</p></section><aside class="order-summary-card"><span class="eyebrow">TU EQUIPO, PREPARADO</span><div class="order-summary-count"><b>{{selection.count}}</b><span>prendas en tu pedido</span></div><ClientOnly><OrderGroups/><p v-if="!selection.lines.length" class="order-summary-empty">Aquí aparecerán tus prendas, organizadas por color y talla.</p></ClientOnly><button class="button dark full" :disabled="!selection.lines.length||checking" @click="validate">{{checking?'Revisando…':'Revisar y enviar'}}<AppIcon name="ArrowRight"/></button><p class="fine-print">Sin registro ni pago online. Confirmaremos precio, disponibilidad y plazos.</p></aside></div><div v-show="review" class="order-review-back"><button class="text-link" @click="review=false"><AppIcon name="ArrowLeft" :size="17"/> Seguir añadiendo prendas</button></div></div><OrderCheckout v-show="review"/><div v-if="!review && selection.count" class="order-mobile-total"><span><b>{{selection.count}}</b> prendas</span><button class="button dark" :disabled="checking" @click="validate">Revisar pedido <AppIcon name="ArrowRight" :size="16"/></button></div></div></template>
